function calculateGtin13(prefix12) {
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    const digit = parseInt(prefix12[i], 10);
    sum += i % 2 === 0 ? digit * 1 : digit * 3;
  }
  const checkDigit = (10 - (sum % 10)) % 10;
  return prefix12 + checkDigit.toString();
}

